// 装配器（仅最后一个分片携带）：合成全局 DB——
//   ["o", {...}]           普通键浅合并（各片键集互不重叠，直接赋值）
//   ["a", key, [..]]       大数组按元素切片，保序 concat
//   ["d", key, {..}]       大字典按键分组切片，组内逐键赋值合并
(function () {
  var db = {};
  window.DB_PARTS.forEach(function (frag) {
    if (frag[0] === "o") {
      Object.keys(frag[1]).forEach(function (k) { db[k] = frag[1][k]; });
    } else if (frag[0] === "d") {
      var dst = db[frag[1]] || (db[frag[1]] = {});
      Object.keys(frag[2]).forEach(function (k) { dst[k] = frag[2][k]; });
    } else {
      db[frag[1]] = (db[frag[1]] || []).concat(frag[2]);
    }
  });
  window.DB_PARTS.length = 0;
  window.DB = db;
})();

// 没有完整简历的官员 → 薄记录占位（app.js renderPerson 兜底依赖，必须保留）
function thinPerson(pid, name) {
  return {
    name, birth: null, native: null, ethnic: null, edu: null, party: null, work: null,
    status: '—', career: null, thin: true,
    srcNote: '该官员暂无可核验的公开简历来源，目前仅有任职记录（roster 级）。' +
             '如你掌握其简历史料（年鉴、公示、新闻），欢迎通过报错通道提供。',
  };
}
